UsbCLACodeUpdater::UsbCLACodeUpdater(USBD_NODE_ID usbNodeId,
		UINT16 usbDeviceType, CLACommManager * pCLAComm) : IUsbCodeUpdater(usbNodeId, usbDeviceType), responseCounter_(0),
		popedPrepareToFlashMsg_(false), masterAppOnly_(false), allAppsMasterDataBoot_(false)
{
	pMyCLAComm_ = pCLAComm;
	pCommMgr_ = 0;
	responseStateMachine_ = waitingForNewInstalledSrc;

	//UPDATER_SYNC
	PAL_absclass::PAL_releaseMutex(update_lock);

#if defined ( __linux__ )
	Debug::trace("UsbCLACodeUpdater", HobString("Constructor Called nodeId = ") + Integer::toString64((int64_t)usbNodeId) + HobString(" device type = ") + Integer::toString(usbDeviceType));
#else
	Debug::trace("UsbCLACodeUpdater", HobString("Constructor Called nodeId = ") + Integer::toString64((__int64)usbNodeId) + HobString(" device type = ") + Integer::toString(usbDeviceType));
#endif
}

UsbCLACodeUpdater::~UsbCLACodeUpdater()
{
	Debug::trace("UsbCLACodeUpdater", HobString("UsbCLACodeUpdater destructor called"));

	if (pCommMgr_)
		delete pCommMgr_;
}

void UsbCLACodeUpdater::requestUpdate(CLASystemStatus laSysStatus)
{
	Debug::trace("UsbCLACodeUpdater", "requestUpdate():  Begin.");
	responseCounter_ = 0;
	burnList_.clear();
	upgradeList_.clear();
	reqUpgradeList_.clear();
	masterAppOnly_ = false;
	allAppsMasterDataBoot_ = false;

	Util::CLockCriticalSection lock( updateCrit );
	//node 2 (master board)
	processSystemStatusMessageForNode(2, HobVersion::CLAAppSW, HobVersion::CLADataSW, HobVersion::CLABootSW, laSysStatus);

	Debug::trace("UsbCLACodeUpdater", "requestUpdate():  Done.");
	//Check if we need to update now
	//sendUpdateRequest();
}

void UsbCLACodeUpdater::sendUpdateRequest()
{
	Debug::trace("UsbCLACodeUpdater", "sendUpdateRequest():  reqUpgradeList_.size() = " + Integer::toString((int) reqUpgradeList_.size()));
	if(reqUpgradeList_.size() > 0)
	{
		responseStateMachine_ = waitingForResponses;
	
		reqIterator_  = reqUpgradeList_.begin();

		while(reqIterator_ != reqUpgradeList_.end())
		{
			dispatchEvent(*reqIterator_);
			reqIterator_++;
		}
	}
	Debug::trace("UsbCLACodeUpdater", "sendUpdateRequest():  Done.");
}

void UsbCLACodeUpdater::processSystemStatusMessageForNode(int nodeNumber,
		HobVersion::VersionType appSoftwareType,
		HobVersion::VersionType dataSoftwareType,
		HobVersion::VersionType bootSoftwareType,
		CLASystemStatus &laSysStatus)
{
	HobString msgDebug = "processSystemStatusMessageForNode(" + Integer::toString(nodeNumber) + "):  ";
	int i;

	i = 2;//The node number for the CLA
	if (i != MAX_NODES)
	{
		Debug::trace("UsbCLACodeUpdater", msgDebug + "masterAppOnly_ = " + Bool::toString(masterAppOnly_) + ",  allAppsMasterDataBoot_ = " + Bool::toString(allAppsMasterDataBoot_));
		//	If Node 2 is not a Manufacturing image, we can include the other nodes and components.
		if (!masterAppOnly_)
		{
			HobVersion hardwareVersion;
			HobVersion labelApplierSoftwareVersion;

			hardwareVersion.setVersionType(HobVersion::CLAControllerHW);
			hardwareVersion.setMajorRevision(1);
			hardwareVersion.setMinorRevision(0);
    	    responseCounter_ += 1;

            Debug::trace("UsbCLACodeUpdater", msgDebug + "responseCounter_ = " + Integer::toString(responseCounter_));

			labelApplierSoftwareVersion.setVersionType(appSoftwareType);
			labelApplierSoftwareVersion.setMajorRevision(laSysStatus.getAppFlashMajor());
			labelApplierSoftwareVersion.setMinorRevision(laSysStatus.getAppFlashMinor());
			if ((nodeNumber == 2) && (labelApplierSoftwareVersion.getMajorRevision() == 0) && (labelApplierSoftwareVersion.getMinorRevision() == 0))
				masterAppOnly_ = true;
			Debug::trace("UsbCLACodeUpdater", msgDebug + "App labelApplierSoftwareVersion = " + Integer::toString(labelApplierSoftwareVersion.getMajorRevision()) + "." + Integer::toString(labelApplierSoftwareVersion.getMinorRevision()) + ",  masterAppOnly_ = " + Bool::toString(masterAppOnly_));

			if (!masterAppOnly_ || (masterAppOnly_ && (nodeNumber == 2)))
			{
				//	If we have a Manufacturing image on Node 2, only the Application will be downloaded first. Then the CLA will need to be reset.

				PeripheralRequestCodeUpdate *pReqPrnCodeUpdate_A = new PeripheralRequestCodeUpdate(usbNodeId_, hardwareVersion, labelApplierSoftwareVersion);			
				reqUpgradeList_.push_back(pReqPrnCodeUpdate_A);
			}

			if (!masterAppOnly_)
			{
				labelApplierSoftwareVersion.setVersionType(dataSoftwareType);
				labelApplierSoftwareVersion.setMajorRevision(laSysStatus.getDataFlashMajor());
				labelApplierSoftwareVersion.setMinorRevision(laSysStatus.getDataFlashMinor());
				if ((nodeNumber == 2) && (labelApplierSoftwareVersion.getMajorRevision() == 0) && (labelApplierSoftwareVersion.getMinorRevision() == 0))
					allAppsMasterDataBoot_ = true;
				Debug::trace("UsbCLACodeUpdater", msgDebug + "Data labelApplierSoftwareVersion = " + Integer::toString(labelApplierSoftwareVersion.getMajorRevision()) + "." + Integer::toString(labelApplierSoftwareVersion.getMinorRevision()));

				if (!allAppsMasterDataBoot_ || (allAppsMasterDataBoot_ && (nodeNumber == 2)))
				{
					//	We can include the other components (Data and Boot).
	    	 		responseCounter_ += 2;

					PeripheralRequestCodeUpdate *pReqPrnCodeUpdate_D = new PeripheralRequestCodeUpdate(usbNodeId_, hardwareVersion, labelApplierSoftwareVersion);			
					reqUpgradeList_.push_back(pReqPrnCodeUpdate_D);

					labelApplierSoftwareVersion.setVersionType(bootSoftwareType);
					labelApplierSoftwareVersion.setMajorRevision(laSysStatus.getBootFlashMajor());
					labelApplierSoftwareVersion.setMinorRevision(laSysStatus.getBootFlashMinor());
					Debug::trace("UsbCLACodeUpdater", msgDebug + "Boot labelApplierSoftwareVersion = " + Integer::toString(labelApplierSoftwareVersion.getMajorRevision()) + "." + Integer::toString(labelApplierSoftwareVersion.getMinorRevision()));

					PeripheralRequestCodeUpdate *pReqPrnCodeUpdate_B = new PeripheralRequestCodeUpdate(usbNodeId_, hardwareVersion, labelApplierSoftwareVersion);			
					reqUpgradeList_.push_back(pReqPrnCodeUpdate_B);
				}
			}
		}
	}
	Debug::trace("UsbCLACodeUpdater", msgDebug + "reqUpgradeList_.size() = " + Integer::toString((int) reqUpgradeList_.size()));
}

void UsbCLACodeUpdater::handleVersionManagerDevEvent(VersionManagerEvent verManagerEvent, const char *recvBuffer)
{
	bool traceOn = Debug::isTracing("UsbCLACodeUpdater");
	HobString msgDebug;

	Util::CLockCriticalSection lock( updateCrit );

	if (traceOn)
		msgDebug = "handleVersionManagerDevEvent(" + Integer::toString(verManagerEvent) + "):  ";

	switch (verManagerEvent)
	{
		case PeripheralUpdateCode:
		{
			PeripheralCodeUpdate codeUpdate(recvBuffer);

			if (traceOn)
			{
				HobString msgDebug2 = msgDebug;
				msgDebug2.append("Response from version manager PeripheralUpdateCode:  responseStateMachine_ = ").append(Integer::toString(responseStateMachine_));
				Debug::trace("UsbCLACodeUpdater", msgDebug2);
			}

			switch(responseStateMachine_)
			{
				case waitingForResponses:
				{
					if (traceOn)
					{
						HobString msgDebug2 = msgDebug;
						msgDebug2.append("WaitingForResponses:  Total received responses so far = ").append(Integer::toString(responseCounter_));
						Debug::trace("UsbCLACodeUpdater", msgDebug2);
					}

					upgradeList_.appendUpgradeVersions(codeUpdate.getCurrentSoftwareVersion(), codeUpdate.getComplexVersion());
					if (codeUpdate.getNodeId() == usbNodeId_)
					{
						responseCounter_--;

						//is upgrade available?
						switch (codeUpdate.getResponseType())
						{
							case SoftwareSystem::AvailableUpgrade:
							{
								if (traceOn)
									Debug::trace("UsbCLACodeUpdater", msgDebug + "SoftwareSystem::AvailableUpgrade");

								bool addToBurnList = false, validSW = false;
								UINT16 swMajorRev = 0, swMinorRev = 0;

								HobVersion::VersionType tmpType = codeUpdate.getVersionType();
								HobComplexVersion * pSoftVer = codeUpdate.getComplexVersion();

								if (pSoftVer)
								{
									swMajorRev = pSoftVer->getMajorRevision();
									swMinorRev = pSoftVer->getMinorRevision();
								}

								if (traceOn)
								{
									HobString msgDebug2 = msgDebug;
#if defined ( __linux__ )
									msgDebug2.append("Ready to flash new software for nodeId: ").append(Integer::toString64((int64_t)codeUpdate.getNodeId()));
#else
									msgDebug2.append("Ready to flash new software for nodeId: ").append(Integer::toString64((__int64)codeUpdate.getNodeId()));
#endif
									msgDebug2.append("	type = ").append(Integer::toString(tmpType));
									msgDebug2.append("	swMajorRev = ").append(Integer::toString(swMajorRev));
									msgDebug2.append("	swMinorRev = ").append(Integer::toString(swMinorRev));
									Debug::trace("UsbCLACodeUpdater", msgDebug2);
								}

								switch (tmpType)
								{
									case HobVersion::CLAAppSW:
									case HobVersion::CLADataSW:
									case HobVersion::CLABootSW:
										{											
											validSW = true;
										}
										break;
									default:
										break;
								}

								if (validSW)
								{
									Debug::trace("UsbCLACodeUpdater", HobString("adding to burn list"));
									addToBurnList = true;
								}

								if (addToBurnList)
								{
									Debug::trace("UsbCLACodeUpdater", HobString("adding the software to the burn list") );

									util_filesystem::Directory *srcDir = codeUpdate.getPath();
									util_filesystem::File sourceFile(srcDir->getFullPath(), "source.bin");

									if (sourceFile.exists() == true)
									{
										Debug::trace("UsbCLACodeUpdater", HobString("source file exists path = ") + sourceFile.getFullPath() );
										//  Add it to the burn list. We will copy and extract the tar file when we need it.
										burnList_.insert(make_pair(tmpType, sourceFile.getFullPath()));
									}
									else
									{
										Debug::trace("UsbCLACodeUpdater", HobString("source file doesnt exist path = ") + sourceFile.getFullPath() );
									}
								}
								break;
							}
							case SoftwareSystem::NotAvailable:
							{
								Debug::trace("UsbCLACodeUpdater", HobString("SoftwareSystem::NotAvailable: Code not available on internal cf") );
								break;
							}
							case SoftwareSystem::AvailableSameVersion:
							{
								Debug::trace("UsbCLACodeUpdater", HobString("SoftwareSystem::AvailableSameVersion") );
								break;
							}
							case SoftwareSystem::retryCntrOver:
							{
								Debug::trace("UsbCLACodeUpdater", HobString("SoftwareSystem::retryCntrOver: Failure counter over limit") );
							}
							default:
							{
								Debug::trace("UsbCLACodeUpdater", HobString("default: Probably invalid hardware version") );
								break;
							}
						}
					}

					//we have all expected responses.
					if ((responseCounter_ <= 0) && (responseStateMachine_ == waitingForResponses))
					{
						Debug::trace("UsbCLACodeUpdater", HobString("Received all responses.") );

						//do we have anything to update?
						if (burnList_.size() > 0)
						{
							Debug::trace("UsbCLACodeUpdater", HobString("There is something to burn. Start the burn process.") );

							//  Transition to the CLA Upgrade page.
							UpgradePeripheral msg(InitiateUpgradeProcess, LabelApplier, CompactLabelApplier_EPSAC2);
							dispatchEvent(&msg);

							PAL_absclass::PAL_sleep(1 * 1 * 1000);		//wait for 5 seconds before sending the CLA upgrade list.

							//update CLA upgrade page with upgrade list!
							dispatchEvent(&upgradeList_);
							Debug::trace("UsbCLACodeUpdater", HobString("upgradeList_ dispatched."));
						}
						else
						{
							//burn list is empty!
							Debug::trace("UsbCLACodeUpdater", HobString("Nothing to install, so just wait for a firmware upgrade.") );

							//tell the CLA to reboot
							pMyCLAComm_->rebootPeripheral();

							responseStateMachine_ = waitingForNewInstalledSrc;
						}
						//if any requests on the list, free.
						while(reqUpgradeList_.empty() != true)
						{
							PeripheralRequestCodeUpdate *pReqPrnCodeUpdate = reqUpgradeList_.front();								
							reqUpgradeList_.pop_front();

							delete pReqPrnCodeUpdate;
						}
					}
				}		
				break;
				case waitingForNewInstalledSrc:
				{
					Debug::trace("UsbCLACodeUpdater", HobString("waitingForNewInstalledSrc: checking for newly installed SW") );																	

					if (codeUpdate.getNodeId() == usbNodeId_)
					{
						Debug::trace("UsbCLACodeUpdater", HobString("waitingForNewInstalledSrc, message destined for the CLA") );																		
						if (codeUpdate.getResponseType() == SoftwareSystem::AvailableUpgrade)
						{
							//we got the first message for firmware upgrade of the CLA.
							//ignore all other messages if any
							responseStateMachine_ = waitingForComponentCheckComplete;
						}
					}
				} 
				break;
				default:
				{
					Debug::trace("UsbCLACodeUpdater", HobString("default: ignoring PeripheralCodeUpdate message because of current state") );																		
				}
				break;
			} 
			break;
		}
		case CancelUpgrade:
		{
			Debug::trace("UsbCLACodeUpdater", msgDebug + "CancelUpgrade:  Will not upgrade the CLA. See if they want to remove the TAR files.");
			VmStatusMsg status(NULL, VMUSBCLARequestRemoveCLATarFiles, HfcResponse::RESPONSESTYLE_OKCANCEL, false);
			dispatchEvent(&status); 

			//tell the CLA to reboot
			pMyCLAComm_->rebootPeripheral();
			break;
		}
		case BeginUpgrade:
		{
			HobString msgDebug2;
			if (traceOn)
			{
				msgDebug2 = msgDebug;
				msgDebug2.append("BeginUpgrade:  ");
				Debug::trace("UsbCLACodeUpdater", msgDebug2 + "Starting to upgrade the CLA.");
			}

			if (pMyCLAComm_)
			{
				if (traceOn)
					Debug::trace("UsbCLACodeUpdater", msgDebug2 + "Creating comm manager.");

				pMyCLAComm_->createCommLink(); 

				//  Notify the CLAManager that we are now Upgrading the CLA.
				LabelApplierGeneric msg((LaEvent) LaCLAUpgradeInProgress, this);
				dispatchEvent(&msg);

				if (traceOn)
					Debug::trace("UsbCLACodeUpdater", msgDebug2 + "Calling setupCodeFlash() in 5 seconds.");

				//  Wait for 5 seconds.
				PAL_absclass::PAL_sleep(1 * 5 * 1000);						

				//send the burn list to the CLA!!!!
				pMyCLAComm_->setupCodeFlash(burnList_);

				responseStateMachine_ = sendingOutCommand;

				if (traceOn)
					Debug::trace("UsbCLACodeUpdater", msgDebug2 + "responseStateMachine_ = sendingOutCommand (" + Integer::toString(responseStateMachine_) + ")");
			}
			else
			{
				if (traceOn)
					Debug::trace("UsbCLACodeUpdater", msgDebug2 + "Failed to create code updater object.");

				responseStateMachine_ = waitingForNewInstalledSrc;

				if (traceOn)
					Debug::trace("UsbCLACodeUpdater", msgDebug2 + "responseStateMachine_ = waitingForNewInstalledSrc (" + Integer::toString(responseStateMachine_) + ")");
			}
			break;
		}
		case ComponentCheckComplete:
		{
			Debug::trace("UsbCLACodeUpdater", msgDebug + "ComponentCheckComplete:  Sending CLASystemRequestStatus.");

			responseStateMachine_ = waitingForNewInstalledSrc;

			LabelApplierSystemRequestStatus lasrs(this);
			const char *pCC = lasrs.serialize();
			pMyCLAComm_->send(pCC, lasrs.getSerializedLength());

			//Also request sysInfo msg here
			//CLAReqSystemInfo lars(this);
			//const char *pRSI = lars.serialize();
			//pMyCLAComm_->send(pRSI, lars.getSerializedLength());

			break;
		}

		default:
			Debug::trace("UsbCLACodeUpdater", HobString("default case - we are not handling this."));
			break;
	}
}

void UsbCLACodeUpdater::shutdownTimeout(void *pObject)
{
	UsbCLACodeUpdater *pUpdater = (UsbCLACodeUpdater *)pObject;

	PAL_absclass::PAL_sleep(1 * 60 * 1000);		//wait for 1 min.

	LabelApplierSystemRequestStatus lasrs(pUpdater);
	lasrs.setSourceObject(pUpdater);

	Debug::trace("UsbCLACodeUpdater", HobString("shutdownTimeout():  sending LabelApplierSystemRequestStatus."));
	const char *pCC = lasrs.serialize();
	pUpdater->pMyCLAComm_->send(pCC, lasrs.getSerializedLength());
}

bool UsbCLACodeUpdater::isUpdateComplete()
{
	bool updateComplete = false;

	if (pMyCLAComm_)
		updateComplete = pMyCLAComm_->areTransactionsComplete();

	Debug::trace("UsbCLACodeUpdater", "isUpdateComplete() == " + HobString(Bool::toString(updateComplete)));
	return updateComplete;
}
